<?php
function overview_signed($n){return ($n>0?'+':'').number_format((int)$n);}
function overview_page_size(){$n=(int)($_GET['per_page']??10);return in_array($n,[10,20,30,50],true)?$n:10;}
function overview_matrix_html($roll,$f){
 $rows=overview_matrix_rows($roll,$f);$html='<div class="overview-table-scroll"><table class="table overview-matrix" data-server-paginated="1"><thead><tr><th>Movement</th><th>Sellable (pcs)</th><th>Non-Sellable (pcs)</th><th>Physical (pcs)</th></tr></thead><tbody>';
 foreach($rows as $i=>$row){$balance=$i===0||$i===count($rows)-1;$html.='<tr'.($balance?' class="overview-balance"':'').'><td>'.e($row[0]).'</td>';foreach(array_slice($row,1) as $v)$html.='<td class="overview-number '.(!$balance&&$v<0?'overview-minus':(!$balance&&$v>0?'overview-plus':'')).'">'.e($balance?number_format($v):overview_signed($v)).'</td>';$html.='</tr>';}
 return $html.'</tbody></table></div>';
}
function overview_page($r){
 $f=$r['filters'];$roll=$r['overview']['rollforward'];$query=report_public_filters($f);$query['page']='reports';$export=$query;unset($export['page']);$size=overview_page_size();$count=count($r['rows']);$offset=min(intdiv(max(0,(int)($_GET['offset']??0)),$size)*$size,max(0,(int)(ceil($count/$size)-1)*$size));
 echo '<link rel="stylesheet" href="assets/overview_reports.css?v=5.9.17"><div class="overview-report"><div class="page-head"><div><h1>Reports</h1><p>Read-only stock balances and operational records.</p></div></div><div class="tabs report-tabs">';
 foreach(access_report_catalog() as $group=>$reports)echo '<a class="tab '.($group==='Overview'?'active':'').'" href="?'.e(http_build_query(array_replace($query,['report'=>array_key_first($reports),'offset'=>0]))).'">'.e($group).'</a>';
 echo '</div><div class="overview-title"><h2>Inventory Operations Summary</h2><p>Stock balances and movements for the selected period.</p></div><div class="card"><form method="get" class="overview-filters" data-overview-filters><input type="hidden" name="page" value="reports"><input type="hidden" name="report" value="overview"><input type="hidden" name="per_page" value="'.$size.'"><label>Product / SKU<select name="product_id" data-product-select><option value="0">All Products</option>';
 foreach(db()->query('SELECT id,name,master_sku,brand FROM products ORDER BY name,id') as $p)echo '<option value="'.(int)$p['id'].'" '.((int)$f['product_id']===(int)$p['id']?'selected':'').'>'.e($p['name'].' · '.$p['brand'].' · '.$p['master_sku']).'</option>';
 echo '</select></label><label>From Date<input type="date" name="from" value="'.e($f['from']).'" max="'.date('Y-m-d').'" required></label><label>To Date<input type="date" name="to" value="'.e($f['to']).'" max="'.date('Y-m-d').'" required></label><label>Brand<select name="brand"><option value="">All Brands</option>';
 foreach(inventory_brand_options() as $brand)echo '<option '.($f['brand']===$brand?'selected':'').'>'.e($brand).'</option>';
 echo '</select></label><label>Main Category<select name="main_category"><option value="">All Main Categories</option>';
 $tree=product_category_tree();foreach($tree as $main=>$subs)echo '<option '.($f['main_category']===$main?'selected':'').'>'.e($main).'</option>';
 echo '</select></label><label>Subcategory<select name="subcategory"><option value="">All Subcategories</option>';$subcats=[];foreach($tree as $main=>$subs)if(!$f['main_category']||$f['main_category']===$main)$subcats=array_merge($subcats,$subs);
 foreach(array_unique($subcats) as $sub)echo '<option '.($f['subcategory']===$sub?'selected':'').'>'.e($sub).'</option>';
 echo '</select></label><div class="overview-filter-bottom"><div class="overview-actions overview-shortcuts">';
 foreach(['Today'=>date('Y-m-d'),'This Week'=>date('Y-m-d',strtotime('monday this week')),'This Month'=>date('Y-m-01')] as $label=>$date)echo '<button type="button" class="btn ghost sm" data-overview-from="'.$date.'" data-overview-to="'.date('Y-m-d').'">'.$label.'</button>';
 echo '</div><div class="overview-actions"><button type="submit" class="btn primary">Generate Report</button><a class="btn ghost" href="?page=reports&amp;report=overview">Clear Filters</a></div></div></form></div>';
 echo '<p class="overview-scope">Period: '.e(report_period_label($f)).' · '.e(report_readable_filters($f)).'</p><div class="overview-ending">';
 $descriptions=['Includes reserved stock still in warehouse','Damaged / Leak / For Repackaging / other Non-Sellable','Sellable + Non-Sellable'];$i=0;
 foreach($r['summary'] as $label=>$qty){echo '<button type="button" class="overview-total '.($i===2?'overview-physical':'').'" data-overview-open><span>'.e(str_replace(' (pcs)','',$label)).'</span><strong>'.number_format((int)$qty).'</strong><small>pcs · '.e($descriptions[$i]).'</small></button>';$i++;}
 echo '</div><div class="card overview-period"><div class="card-head"><h3>Movements during period</h3><button type="button" class="btn secondary sm" data-overview-open>View Movement Breakdown</button></div><div class="overview-movement-strip">';
 $m=$roll['movements'];$releases=-($m['dispatch']['physical']+$m['releases']['physical']+$m['disposal']['physical']+$m['ns_releases']['physical']);
 foreach(['Beginning Balance Added'=>$m['beginning']['physical'],'Physical Receipts'=>$m['receipts']['physical'],'Physical Releases'=>-$releases,'Moved to Non-Sellable'=>$m['to_nonsellable']['restricted']] as $label=>$qty)echo '<div><span>'.e($label).'</span><b>'.e($label==='Moved to Non-Sellable'?number_format($qty):overview_signed($qty)).' pcs</b></div>';
 echo '</div><p class="small muted">Physical releases include dispatch, manual / borrowed releases and Non-Sellable releases. Open the breakdown for recovery, adjustments and linked reversals.</p></div><p class="overview-notice">ⓘ To Ship reserves stock; dispatch deducts it. Current reservation quantities are not mixed into this historical report.</p>';
 $matrix=overview_matrix_html($roll,$f);$all=['name'=>'All filtered products · '.$count.' items','html'=>$matrix];
 echo '<details class="card overview-breakdown" id="overviewBreakdown"><summary>Movement Breakdown</summary><div class="overview-breakdown-head"><div><strong data-overview-detail-name>'.e($all['name']).'</strong><p class="small muted">'.e(report_period_label($f)).' · Signed changes in pcs</p></div><div class="overview-actions"><button type="button" class="btn ghost sm" data-overview-all hidden>All filtered products</button><a class="btn secondary sm" data-overview-history hidden>Open Full Movement History</a></div></div><div data-overview-matrix>'.$matrix.'</div><p class="small muted overview-note">Moved to Non-Sellable and recovered stock stay inside the warehouse. Platform transfers change allocations only. Returns increase stock after actual receipt.</p></details>';
 echo '<div class="card overview-products"><div class="card-head"><div><h3>Product Summary</h3><p>'.number_format($count).' matching products · All quantities in pcs</p></div><div class="overview-actions"><a class="btn secondary" href="report.php?'.e(http_build_query($export+['format'=>'xlsx'])).'">Download Excel</a><a class="btn ghost" target="_blank" rel="noopener" href="report.php?'.e(http_build_query($export+['format'=>'print'])).'">Print / Save as PDF</a></div></div><p class="small muted">Generated '.e($r['generated']).' · '.e($r['user']).'</p><div class="overview-table-scroll"><table class="table overview-product-table" data-server-paginated="1"><thead><tr><th>Product / SKU</th><th>Opening Sellable</th><th>Net Sellable Movement</th><th>Ending Sellable</th><th>Ending Non-Sellable</th><th>Total Physical</th><th>Action</th></tr></thead><tbody>';
 $payload=['all'=>$all,'products'=>[]];foreach(array_slice($r['rows'],$offset,$size,true) as $index=>$row){$detail=$r['overview']['details'][$index];$pid=$detail['product_id'];$item=['name'=>$row[1].' · '.$row[0],'html'=>overview_matrix_html($detail['rollforward'],$f)];if(access_report_allowed('movement'))$item['history']=$r['links'][$index];$payload['products'][(string)$pid]=$item;
  echo '<tr><td>'.e($row[1]).'<small>'.e($row[0]).'</small></td>';foreach(array_slice($row,2) as $col=>$v)echo '<td class="overview-number">'.e($col===1?overview_signed($v):number_format($v)).'</td>';echo '<td><button type="button" class="btn ghost sm" data-overview-product="'.$pid.'">View Movements</button></td></tr>';
 }
 if(!$count)echo '<tr><td colspan="7">No matching products. Adjust your filters.</td></tr>';
 echo '</tbody><tfoot><tr><td>Filtered Total · '.number_format($count).' products</td>';foreach(array_slice($r['totals_row'],2) as $col=>$v)echo '<td class="overview-number">'.e($col===1?overview_signed($v):number_format($v)).'</td>';echo '<td></td></tr></tfoot></table></div>';
 $pageParams=$query+['per_page'=>$size];$pager=rs8_pagination($count,$offset,$size,$pageParams,'offset',false,'Totals and exports include all matching products across every page.');$label='<label class="overview-size"><select data-overview-size aria-label="Products per page">';foreach([10,20,30,50] as $n)$label.='<option value="'.$n.'"'.($size===$n?' selected':'').'>'.$n.'</option>';$label.='</select><span>Rows per page</span></label>';
 echo str_replace('</span></div><div class="pagination-buttons">','</span>'.$label.'</div><div class="pagination-buttons">',$pager).'</div>';
 $platformQuery=array_replace($query,['report'=>'platforms','as_of'=>$f['to']]);unset($platformQuery['from'],$platformQuery['to']);
 echo '<div class="card overview-platforms"><div><h3>Platform allocations</h3><p class="small muted">Lazada · Shopee · TikTok · Website · Allocation at the selected ending date</p></div><a class="btn secondary" href="?'.e(http_build_query($platformQuery)).'">View Platform Breakdown</a></div><div class="overview-notes">';foreach($r['notes'] as $note)echo '<p class="small muted">'.e($note).'</p>';echo '</div></div><script type="application/json" id="overviewReportData">'.json_encode($payload,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR).'</script><script src="assets/overview_reports.js?v=5.9.17" defer></script>';
}
